```

### 4.2 Cart Context (Redux Toolkit + RTK Query)

```ts
// store/cartSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';

interface CartItem {
  productId: string;
  quantity: number;
}

interface CartState {
  items: CartItem[];
}

const initialState: CartState = { items: [] };

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addToCart(state, action: PayloadAction<CartItem>) {
      const existing = state.items.find(i => i.productId === action.payload.productId);
      if (existing) {
        existing.quantity += action.payload.quantity;
      } else {
        state.items.push(action.payload);
      }
    },
    removeFromCart(state, action: PayloadAction<string>) {
      state.items = state.items.filter(i => i.productId !== action.payload);
    },
    clearCart(state) {
      state.items = [];
    }
  }
});

export const { addToCart, removeFromCart, clearCart } = cartSlice.actions;
export default cartSlice.reducer;
```

```ts
// store/store.ts
import { configureStore } from '@reduxjs/toolkit';
import cartReducer from './cartSlice';

export const store = configureStore({
  reducer: {
    cart: cartReducer
  }
});

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
```

```tsx
// pages/_app.tsx
import { Provider } from 'react-redux';
import { store } from '../store/store';
import '../styles/globals.css';

function MyApp({ Component, pageProps }) {
  return (
    <Provider store={store}>
      <Component {...pageProps} />
    </Provider>
  );
}

export default MyApp;
```

### 4.3 API Client (Axios)

```ts
// services/api.ts
import axios from 'axios';

const api = axios.create({
  baseURL: process.env.NEXT_PUBLIC_API_URL || 'https://api.example.com',
  headers: { 'Content-Type': 'application/json' }
});

export default api;
```

### 4.4 Fetching Products (RTK Query)

```ts
// services/productApi.ts
import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';
import api from './api';

export const productApi = createApi({
  reducerPath: 'productApi',
  baseQuery: fetchBaseQuery({ baseUrl: '/' }),
  endpoints: builder => ({
    getProducts: builder.query({
      query: () => '/products',
      transformResponse: (response: any) => response.data
    }),
    getProductById: builder.query({
      query: (id: string) => `/products/${id}`,
      transformResponse: (response: any) => response.data
    })
  })
});

export const { useGetProductsQuery, useGetProductByIdQuery } = productApi;
```

Add the API slice to the store:

```ts
// store/store.ts (add to reducer)
import { productApi } from '../services/productApi';

export const store = configureStore({
  reducer: {
    cart: cartReducer,
    [productApi.reducerPath]: productApi.reducer
  },
  middleware: getDefaultMiddleware =>
    getDefaultMiddleware().concat(productApi.middleware)
});
```

### 4.5 Checkout Flow (Stripe Integration)

```tsx
// pages/checkout.tsx
import { useSelector } from 'react-redux';
import { RootState } from '../store/store';
import { loadStripe } from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';
import CheckoutForm from '../components/CheckoutForm';

const stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY!);

export default function Checkout() {
  const cartItems = useSelector((state: RootState) => state.cart.items);

  return (
    <Elements stripe={stripePromise}>
      <CheckoutForm items={cartItems} />
    </Elements>
  );
}
```

```tsx
// components/CheckoutForm.tsx
import { CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { useState } from 'react';
import api from '../services/api';

export default function CheckoutForm({ items }) {
  const stripe = useStripe();
  const elements = useElements();
  const [loading, setLoading] = useState(false);

  const handleSubmit = async e => {
    e.preventDefault();
    if (!stripe || !elements) return;

    setLoading(true);
    const { data } = await api.post('/checkout', { items });

    const result = await stripe.confirmCardPayment(data.clientSecret, {
      payment_method: {
        card: elements.getElement(CardElement),
        billing_details: { email: 'customer@example.com' }
      }
    });

    if (result.error) {
      console.error(result.error.message);
    } else if (result.paymentIntent?.status === 'succeeded') {
      console.log('Payment succeeded!');
    }
    setLoading(false);
  };

  return (
    <form onSubmit={handleSubmit} className="max-w-md mx-auto p-4">
      <CardElement className="border p-2 rounded mb-4" />
      <button
        type="submit"
        disabled={!stripe || loading}
        className="bg-indigo-600 text-white px-4 py-2 rounded disabled:opacity-50"
      >
        {loading ? 'Processing…' : 'Pay Now'}
      </button>
    </form>
  );
}
```

> **Security note:** Never expose your secret keys on the client. All sensitive operations (creating PaymentIntent, verifying webhook events) must happen on a secure server (e.g., Next.js API route or a separate Node/Express server).

